class Solution {
public:
    long long countTheNumOfKFreeSubsets(std::vector<int>& nums, int k) {
        std::unordered_map<int, std::vector<int>> groups;
        for (int x : nums) groups[x % k].push_back(x);
        long long total = 1;
        for (auto& [rem, vals] : groups) {
            std::sort(vals.begin(), vals.end());
            std::vector<int> chains;
            int curr_len = 1;
            for (int i = 1; i < (int)vals.size(); ++i) {
                if (vals[i] == vals[i - 1] + k) {
                    curr_len++;
                } else {
                    chains.push_back(curr_len);
                    curr_len = 1;
                }
            }
            chains.push_back(curr_len);
            for (int L : chains) {
                long long f0 = 1, f1 = 2;
                for (int step = 1; step < L; ++step) {
                    long long nxt = f0 + f1;
                    f0 = f1;
                    f1 = nxt;
                }
                total *= f1;
            }
        }
        return total;
    }
};

class Solution {
    public long countTheNumOfKFreeSubsets(int[] nums, int k) {
        java.util.Map<Integer, java.util.List<Integer>> groups = new java.util.HashMap<>();
        for (int x : nums) {
            groups.computeIfAbsent(x % k, key -> new java.util.ArrayList<>()).add(x);
        }
        long total = 1;
        for (java.util.List<Integer> vals : groups.values()) {
            java.util.Collections.sort(vals);
            java.util.List<Integer> chains = new java.util.ArrayList<>();
            int currLen = 1;
            for (int i = 1; i < vals.size(); i++) {
                if (vals.get(i) == vals.get(i - 1) + k) {
                    currLen++;
                } else {
                    chains.add(currLen);
                    currLen = 1;
                }
            }
            chains.add(currLen);
            for (int L : chains) {
                long f0 = 1, f1 = 2;
                for (int step = 1; step < L; step++) {
                    long nxt = f0 + f1;
                    f0 = f1;
                    f1 = nxt;
                }
                total *= f1;
            }
        }
        return total;
    }
}

var countTheNumOfKFreeSubsets = function(nums, k) {
    const groups = new Map();
    for (const x of nums) {
        const rem = x % k;
        if (!groups.has(rem)) groups.set(rem, []);
        groups.get(rem).push(x);
    }
    let total = 1n;
    for (const vals of groups.values()) {
        vals.sort((a, b) => a - b);
        const chains = [];
        let currLen = 1;
        for (let i = 1; i < vals.length; i++) {
            if (vals[i] === vals[i - 1] + k) {
                currLen++;
            } else {
                chains.push(currLen);
                currLen = 1;
            }
        }
        chains.push(currLen);
        for (const L of chains) {
            let f0 = 1n, f1 = 2n;
            for (let step = 1; step < L; step++) {
                let nxt = f0 + f1;
                f0 = f1;
                f1 = nxt;
            }
            total *= f1;
        }
    }
    return Number(total);
};
